def solve_n_queens_bitmask(n, fixed):
    ans = [-1] * n
    for r, c in fixed.items():
        ans[r] = c

    def solve(row, cols, diag1, diag2):
        if row == n:
            return True
        if ans[row] != -1:
            c = ans[row]
            if (cols & (1 << c)) or (diag1 & (1 << (row + c))) or (diag2 & (1 << (row - c + n - 1))):
                return False
            return solve(row + 1, cols | (1 << c), diag1 | (1 << (row + c)), diag2 | (1 << (row - c + n - 1)))

        for c in range(n):
            if not (cols & (1 << c)) and not (diag1 & (1 << (row + c))) and not (diag2 & (1 << (row - c + n - 1))):
                ans[row] = c
                if solve(row + 1, cols | (1 << c), diag1 | (1 << (row + c)), diag2 | (1 << (row - c + n - 1))):
                    return True
        ans[row] = -1
        return False

    if solve(0, 0, 0, 0):
        return ans
    return None

fixed = {11: 8, 16: 14, 18: 11, 21: 13}
print(solve_n_queens_bitmask(22, fixed))

from z3 import *

n = 22
fixed = {11: 8, 16: 14, 18: 11, 21: 13}

s = Solver()
Q = [Int(f'Q_{i}') for i in range(n)]

for i in range(n):
    s.add(Q[i] >= 0, Q[i] < n)

s.add(Distinct(Q))

for i in range(n):
    for j in range(i + 1, n):
        s.add(Q[i] - Q[j] != i - j)
        s.add(Q[i] - Q[j] != j - i)

for r, c in fixed.items():
    s.add(Q[r] == c)

if s.check() == sat:
    m = s.model()
    ans = [m.evaluate(Q[i]).as_long() for i in range(n)]
    print(ans)
else:
    print("UNSAT")

from pysat.solvers import Glucose3

n = 22
fixed = {11: 8, 16: 14, 18: 11, 21: 13}

def var(r, c):
    return r * n + c + 1

solver = Glucose3()

# Each row has exactly one queen
for r in range(n):
    solver.add_clause([var(r, c) for c in range(n)])
    for c1 in range(n):
        for c2 in range(c1 + 1, n):
            solver.add_clause([-var(r, c1), -var(r, c2)])

# Each column has exactly one queen
for c in range(n):
    solver.add_clause([var(r, c) for r in range(n)])
    for r1 in range(n):
        for r2 in range(r1 + 1, n):
            solver.add_clause([-var(r1, c), -var(r2, c)])

# Diagonals
for d in range(2 * n - 1):
    # diag1: r + c = d
    diag1 = []
    for r in range(n):
        c = d - r
        if 0 <= c < n:
            diag1.append(var(r, c))
    for i in range(len(diag1)):
        for j in range(i + 1, len(diag1)):
            solver.add_clause([-diag1[i], -diag1[j]])

    # diag2: r - c + n - 1 = d
    diag2 = []
    for r in range(n):
        c = r - d + n - 1
        if 0 <= c < n:
            diag2.append(var(r, c))
    for i in range(len(diag2)):
        for j in range(i + 1, len(diag2)):
            solver.add_clause([-diag2[i], -diag2[j]])

# Fixed assignments
for r, c in fixed.items():
    solver.add_clause([var(r, c)])

if solver.solve():
    model = solver.get_model()
    ans = [-1] * n
    for val in model:
        if val > 0:
            val -= 1
            r, c = val // n, val % n
            ans[r] = c
    print(ans)
else:
    print("UNSAT")
